<template>
  <div class="app-container return-management">
    <div class="page-heading"><p class="muted">合包按实际关联关系展示，资金与货物进度分别跟踪。</p><el-button v-hasPermi="['order:settings:query']" size="small" icon="el-icon-setting" @click="$router.push('/oms-order/businessSettings')">业务设置</el-button></div>
    <el-tabs v-model="query.view" @tab-click="changeView"><el-tab-pane v-for="v in views" :key="v.value" :name="v.value" :label="v.label" /></el-tabs>
    <p class="view-hint">{{ currentView.hint }}</p>
    <el-form inline size="small" class="filters" @submit.native.prevent="search">
      <el-form-item label="单号"><el-select v-model="query.numberType" class="number-type"><el-option v-for="(label,key) in numberTypes" :key="key" :value="key" :label="label" /></el-select><el-input v-model.trim="query.number" class="number-input" clearable placeholder="完整单号；多个用逗号或空格分隔" @keyup.enter.native="search" @paste.native="pasteNumbers" /></el-form-item>
      <el-form-item label="店铺"><el-select v-model="query.channelId" clearable filterable placeholder="全部店铺"><el-option v-for="s in channels" :key="s.channel_id" :value="s.channel_id" :label="s.channel_name" /></el-select></el-form-item>
      <el-form-item label="接收仓"><el-select v-model="query.store" clearable filterable placeholder="全部接收仓"><el-option v-for="s in stores" :key="s.code" :value="s.code" :label="s.name" /></el-select></el-form-item>
      <el-form-item label="仓库交互"><el-select v-model="query.warehouse" clearable placeholder="全部仓库交互状态"><el-option v-for="(label,key) in warehouseFilters" :key="key" :value="key" :label="label" /></el-select></el-form-item>
      <el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button type="text" @click="advanced=!advanced">{{ advanced?'收起筛选':'更多筛选' }}</el-button></el-form-item>
      <div v-show="advanced" class="advanced">
        <el-form-item label="实际商品"><el-input v-model.trim="query.product" clearable placeholder="商品名称 / 实际退回 SKU" @keyup.enter.native="search" /></el-form-item>
        <el-form-item label="来源售后"><el-select v-model="query.kind" clearable><el-option value="REFUND" label="退款退回" /><el-option value="EXCHANGE" label="换货退回" /></el-select></el-form-item>
        <el-form-item v-if="query.view!=='TASK'" label="合包类型"><el-select v-model="query.merge" clearable placeholder="全部"><el-option value="SINGLE" label="单一退回来源" /><el-option value="MERGED" label="多来源合包" /><el-option value="REFUND_MULTI" label="多退款合包" /><el-option value="EXCHANGE_MULTI" label="多换货合包" /><el-option value="MIXED" label="退款 + 换货合包" /></el-select></el-form-item>
        <el-form-item label="商品身份"><el-select v-model="query.itemKind" clearable><el-option value="PURCHASE" label="购买商品" /><el-option value="GIFT" label="关联赠品" /></el-select></el-form-item>
        <el-form-item label="退回方式"><el-select v-model="query.mode" clearable><el-option value="RETURN" label="买家寄回" /><el-option value="INTERCEPT" label="在途拦截退回" /><el-option value="REFUSAL" label="拒收退回" /></el-select></el-form-item>
        <el-form-item><el-checkbox v-model="query.refundOnly" true-label="1" false-label="">仅退款但需退货</el-checkbox></el-form-item>
        <el-form-item label="创建时间"><el-date-picker v-model="dates" type="daterange" value-format="yyyy-MM-dd" range-separator="至" start-placeholder="默认近30天" end-placeholder="完整单号可跨时间查" /></el-form-item>
      </div>
    </el-form>
    <div class="buckets"><button v-for="b in buckets" :key="b.value" :class="{selected:query.stage===b.value}" @click="query.stage=b.value;search()">{{ b.label }} <span>{{ counts[b.value] || 0 }}</span></button></div>
    <el-alert v-if="sync.warning" :title="sync.warning" type="warning" show-icon :closable="false" />
    <el-alert v-else-if="sync.updating" :title="'正在更新查询进度，尚有 '+sync.pending+' 项来源待同步；完成后自动刷新。'" type="info" show-icon :closable="false" />
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <div class="list-heading"><span class="muted">共 {{ total }} {{ currentView.unit }}<span v-if="query.number"> · 已按来源单号定位</span></span><div><el-button v-hasPermi="['order:return:export']" size="small" :loading="exporting" @click="exportRows">导出查询结果</el-button><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="load">刷新列表</el-button></div></div>
    <el-table v-loading="loading" :data="rows" row-key="group_key" size="small" :max-height="tableHeight" :empty-text="error?'查询失败，请重试':'暂无符合条件的退货记录'">
      <el-table-column :label="query.view==='TASK'?'退货来源':query.view==='PARCEL'?'退回包裹':'实际入库单'" min-width="230"><template slot-scope="{row}"><el-button class="number" type="text" @click="open(row)">{{ identity(row) }}</el-button><div class="muted">{{ shop(row.channel_id) }}<span v-if="Number(row.channel_count)>1"> · 多店铺来源</span></div><div class="source-tags"><el-tag size="mini" :type="row.refund_count&&row.exchange_count?'warning':'info'">{{ sourceText(row) }}</el-tag><el-tag v-if="row.has_gift" size="mini" type="warning">含赠品</el-tag><el-tag v-if="row.refund_only" size="mini">含仅退款退货</el-tag></div><div class="muted">{{ row.source_count }} 项退回来源 · {{ row.create_time }}</div></template></el-table-column>
      <el-table-column label="实际退回商品 / 原平台子单" min-width="230"><template slot-scope="{row}"><div v-for="m in (row.products || row.members).slice(0,2)" :key="m.id" class="product"><strong>{{ m.goods_name || m.sku_sn || '待明确实际商品' }}</strong><el-tag v-if="m.is_gift" size="mini" type="warning">赠品</el-tag><div class="muted">{{ m.sku_sn || 'SKU 待确认' }}</div><div class="muted">子单 {{ m.platform_oid }}</div></div><el-button v-if="row.product_count>2" type="text" @click="open(row)">查看全部 {{ row.product_count }} 种商品</el-button></template></el-table-column>
      <el-table-column label="数量进度" min-width="160"><template slot-scope="{row}"><div class="quantity-line"><span>应退</span><b>{{ quantityText(row.units,'quantity') }}</b></div><div class="quantity-line"><span>已确认实收</span><b>{{ quantityText(row.units,'accepted_quantity') }}</b></div><div class="quantity-line"><span>已入库</span><b>{{ quantityText(row.units,'posted_quantity') }}</b></div><div v-if="row.pending_count" class="warning">{{ row.pending_count }} 条实收待归属</div></template></el-table-column>
      <el-table-column label="接收仓 / 退回物流" min-width="205"><template slot-scope="{row}"><div>{{ store(row.store_code) }}</div><div v-if="row.waybill" class="tracking">{{ row.carrier || '承运商待确认' }} · {{ row.waybill }}<el-button v-clipboard:copy="row.waybill" type="text" icon="el-icon-document-copy" title="复制退回运单" /></div><div v-else class="muted">退回运单尚未提供</div><div class="muted">货主 {{ row.owner_code || '待确认' }}</div></template></el-table-column>
      <el-table-column label="仓库交互" min-width="235"><template slot-scope="{row}"><return-warehouse-status :row="row" @open="openWarehouse(row)" /></template></el-table-column>
      <el-table-column label="当前进度 / 下一步" min-width="230"><template slot-scope="{row}"><el-tag :type="tone(row.stage)" size="small">{{ row.incomplete?'来源同步中':stageLabels[row.stage] }}</el-tag><p class="next-step" :class="{warning:row.stage==='NEED_CHECK'}">{{ nextStep(row) }}</p><div class="muted">进度核对 {{ row.sync_time }}</div></template></el-table-column>
      <el-table-column label="关联仓单" min-width="195"><template slot-scope="{row}"><router-link v-if="row.return_sn" :to="ticket(row)">{{ row.return_sn }}</router-link><div v-else class="muted">尚未生成实际入库单</div><el-button v-if="row.parcel_sn&&query.view!=='PARCEL'" type="text" @click="locateParcel(row)">查看退回包裹</el-button><div v-if="query.view==='TASK'&&row.members[0]" class="muted">原发货 {{ row.members[0].original_shipment_sn || '待核对' }}</div></template></el-table-column>
      <el-table-column label="操作" width="80" fixed="right"><template slot-scope="{row}"><el-button v-hasPermi="['order:return:query']" type="text" @click="open(row)">查看详情</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" :page-sizes="[20,50]" @pagination="load" />
    <el-drawer :title="documentSn?'退货入库单详情':'退货查询详情'" :visible.sync="visible" size="min(1280px,96vw)" append-to-body :wrapper-closable="false">
      <return-document-detail v-if="documentSn&&visible" :key="documentSn" :sn="documentSn" :source-number="query.number" :initial-tab="documentTab" :warehouses="stores" />
      <div v-loading="detailLoading" class="detail" v-else-if="detail">
        <div class="detail-heading"><div><h3>{{ identity(detail) }}</h3><p class="muted">{{ sourceText(detail) }} · {{ detail.source_count }} 项实际来源 · {{ store(detail.store_code) }}</p></div><el-tag :type="tone(detail.stage)">{{ stageLabels[detail.stage] }}</el-tag></div>
        <el-alert :title="nextStep(detail)" :type="detail.stage==='NEED_CHECK'?'warning':'info'" :closable="false" show-icon />
        <div class="metrics"><article v-for="m in metrics" :key="m.field"><span>{{ m.label }}</span><strong>{{ quantityText(detail.units,m.field) }}</strong></article></div>
        <p v-if="detail.pending_count" class="warning">另有 {{ detail.pending_count }} 条实收回传待确认归属，尚未计入各来源实收及库存。</p>
        <div class="logistics"><div><span>实际退回运单</span><b>{{ detail.carrier || '承运商待确认' }} · {{ detail.waybill || '尚未提供' }}</b></div><div><span>接收仓 / 货主</span><b>{{ store(detail.store_code) }} / {{ detail.owner_code || '待确认' }}</b></div><div v-if="detail.dispatch_after"><span>归集到期</span><b>{{ detail.dispatch_after }}</b></div><div><span>实际入库单</span><router-link v-if="detail.return_sn" :to="ticket(detail)">{{ detail.return_sn }}</router-link><b v-else>尚未生成</b></div></div>
        <div class="section-heading"><h3>{{ query.view==='TASK'?'本任务实际商品与来源':'整个包裹 / 仓单的来源归属' }}</h3><el-tag v-if="detail.matched_count" size="mini">高亮命中来源</el-tag></div>
        <p class="muted">资金仍归原支付子单，实物按实际发货来源退回。购买商品与赠品、退款与换货分别追溯。</p>
        <el-table :data="detail.members" size="small" :row-class-name="memberClass">
          <el-table-column label="来源售后 / 原订单" min-width="230"><template slot-scope="{row}"><el-tag size="mini" :type="row.owner_kind==='EXCHANGE'?'':'warning'">{{ row.owner_kind==='EXCHANGE'?'换货':'退款' }}</el-tag><el-tag v-if="row.matched" size="mini" type="success">命中来源</el-tag><router-link :to="sourceLink(row)">{{ row.owner_sn }}</router-link><div><router-link :to="{path:'/oms-order/business',query:{orderId:row.order_id}}">{{ row.order_sn }}</router-link></div><div class="muted">平台主单 {{ row.platform_tid }}</div><div class="muted">平台子单 {{ row.platform_oid }}</div></template></el-table-column>
          <el-table-column label="实际退回商品" min-width="205"><template slot-scope="{row}"><strong>{{ row.goods_name || '待明确实际商品' }}</strong><el-tag v-if="row.is_gift" type="warning" size="mini">赠品</el-tag><div class="muted">{{ row.sku_sn || 'SKU 待确认' }}</div><div class="muted">{{ modes[row.return_mode] || row.return_mode }}</div></template></el-table-column>
          <el-table-column label="应退 / 实收 / 入库" min-width="165"><template slot-scope="{row}"><div>应退 {{ row.quantity_known ? row.quantity+' '+row.unit : '待确认数量' }}</div><div>实收 {{ row.accepted_quantity }} {{ row.unit }}</div><div>入库 {{ row.posted_quantity }} {{ row.unit }}</div><div v-if="row.waived_quantity" class="muted">已确认免退 {{ row.waived_quantity }} {{ row.unit }}</div></template></el-table-column>
          <el-table-column label="原实际发货与运单" min-width="205"><template slot-scope="{row}"><div>{{ row.original_shipment_sn || '待明确实际发货来源' }}</div><div class="muted">去程运单 {{ row.outbound_waybills || '尚未提供' }}</div><div v-if="row.warehouse&&row.warehouse.unit_cost!=null" class="muted">原出库成本 {{ row.warehouse.unit_cost }} / {{ row.unit }}</div><div v-if="row.warehouse&&row.warehouse.generation" class="muted">第 {{ row.warehouse.generation }} 次退回安排</div></template></el-table-column>
        </el-table>
        <el-collapse class="warehouse-trace"><el-collapse-item title="仓库受理与来源台账" name="warehouse"><el-table :data="detail.members.filter(m=>m.warehouse&&m.warehouse.part_key)" size="small"><el-table-column prop="owner_sn" label="所属售后" min-width="250" /><el-table-column label="仓库下发与受理" min-width="240"><template slot-scope="{row}"><div>{{ dispatchLabels[row.warehouse.dispatch_state] || '尚未下发' }}</div><div class="muted">受理号 {{ row.warehouse.external_order || '尚未返回' }}</div><div v-if="row.warehouse.last_error" class="warning">{{ row.warehouse.last_error }}</div></template></el-table-column><el-table-column label="原来源记录 / 建立时间" min-width="250"><template slot-scope="{row}"><div>{{ row.warehouse.source_return_sn }}</div><div class="muted">{{ row.warehouse.source_created }}</div></template></el-table-column></el-table></el-collapse-item></el-collapse>
        <p class="scope-note">本页用于查询与追溯。退回安排、合包处理及实收核对请进入对应来源售后查看处理记录；共同操作沿用全部关联来源的权限和版本校验。</p>
      </div>
    </el-drawer>
  </div>
</template>
<script>
import { actions as interactionActions, results as interactionResults } from '../warehouse/wmsLogLabels'
import ReturnDocumentDetail from './ReturnDocumentDetail'
import ReturnWarehouseStatus from './ReturnWarehouseStatus'
import { warehouseFilters, warehouseText } from './returnDocumentPresentation'
import { returnList, returnDetail, returnCatalog, returnExport } from '@/api/order/returns'
import { views, buckets, stageLabels, quantityText, sourceText, nextStep, sourceLink, csvCell } from './returnManagementPresentation'
const defaults = () => ({ view: 'TASK', numberType: 'ANY', number: '', channelId: '', store: '', product: '', kind: '', itemKind: '', mode: '', merge: '', refundOnly: '', stage: '', warehouse: '', pageNum: 1, pageSize: 20 })
export default {
  name: 'Returns', components: { ReturnDocumentDetail, ReturnWarehouseStatus }, data: () => ({ views, buckets, stageLabels, warehouseFilters, documentSn: '', documentTab: 'items', query: defaults(), dates: [], advanced: false, rows: [], total: 0, counts: {}, channels: [], stores: [], sync: {}, loading: false, exporting: false, error: '', visible: false, detail: null, detailLoading: false, sequence: 0, detailSequence: 0, timer: null, height: window.innerHeight, metrics: [{ label: '应退数量', field: 'quantity' }, { label: '已确认实收', field: 'accepted_quantity' }, { label: '已入库', field: 'posted_quantity' }, { label: '尚未实收', field: 'remaining_quantity' }], modes: { RETURN: '买家寄回', INTERCEPT: '在途拦截退回', REFUSAL: '拒收退回' }, numberTypes: { ANY: '全部单号', OWNER: '退款 / 换货单号', PLATFORM_AFTERSALE: '平台售后单号', ORDER: '业务订单号', TID: '平台主订单号', OID: '平台子订单号', SHIPMENT: '原实际发货单号', WAYBILL: '退回运单号', OUTBOUND_WAYBILL: '原发货运单号', PARCEL: '退回包裹号', DOCUMENT: '退货入库单号' }}),
  computed: { currentView() { return views.find(v => v.value === this.query.view) }, tableHeight() { return Math.max(300, this.height - (this.advanced ? 540 : 430)) }, dispatchLabels() { return { PENDING: '待下发', SENDING: '下发中', ACCEPTED: '仓库已接单', UNKNOWN: '下发结果待确认', FAILED: '下发失败', CANCELED: '仓库已确认截停' } } },
  created() { const q = this.$route.query; if (views.some(v => v.value === q.view)) this.query.view = q.view; if (q.number) this.query.number = String(q.number); if (q.document) { this.documentSn = String(q.document); this.documentTab = q.tab === 'interactions' ? 'interactions' : 'items'; this.visible = true } this.initialize() },
  mounted() { window.addEventListener('resize', this.resize) }, beforeDestroy() { this.sequence++; this.detailSequence++; clearTimeout(this.timer); window.removeEventListener('resize', this.resize) },
  methods: {
    quantityText, sourceText, nextStep, sourceLink, warehouseText,
    async initialize() { try { const c = (await returnCatalog()).data; this.channels = c.channels || []; this.stores = (c.warehouses || []).map(w => ({ code: w.code || w.wms_simulation_code || w.store_code, name: w.name || w.wms_simulation_name || w.store_name || w.code || w.wms_simulation_code })) } catch (_) { this.error = '店铺或仓库选项加载失败，可刷新重试' } this.load() },
    filters() { return { ...this.query, from: this.dates && this.dates[0] || '', to: this.dates && this.dates[1] || '' } },
    resize() { this.height = window.innerHeight },
    pasteNumbers(event) { const text = (event.clipboardData || window.clipboardData).getData("text"); if (/[\r\n]/.test(text)) { event.preventDefault(); this.query.number = text.trim().replace(/[\r\n]+/g, " ") } },
    changeView() { this.query.merge = ''; this.query.stage = ''; this.search() }, search() { this.query.pageNum = 1; this.load() }, reset() { const view = this.query.view; this.query = { ...defaults(), view }; this.dates = []; this.search() },
    async load() { clearTimeout(this.timer); const seq = ++this.sequence; this.loading = true; this.error = ''; try { const data = (await returnList(this.filters())).data; if (seq !== this.sequence) return; this.rows = data.rows || []; this.total = Number(data.total); this.counts = data.buckets || {}; this.sync = data.synchronization || {}; if (this.sync.updating && !this.sync.warning) this.timer = setTimeout(() => this.load(), 1500) } catch (e) { if (seq === this.sequence) { this.error = '退货查询未完成，请核对筛选条件或刷新重试'; this.rows = []; this.total = 0; this.counts = {} } } finally { if (seq === this.sequence) this.loading = false } },
    shop(id) { const s = this.channels.find(c => Number(c.channel_id) === Number(id)); return s ? s.channel_name : '店铺 ' + id }, store(code) { const s = this.stores.find(w => w.code === code); return s ? s.name : code || '接收仓待确认' },
    identity(row) { return row.view === 'DOCUMENT' ? row.return_sn : row.view === 'PARCEL' ? row.parcel_sn || '独立退回 · ' + (row.waybill || row.return_sn) : (row.members[0] || {}).owner_sn || '退货任务' },
    tone(stage) { return stage === 'DONE' ? 'success' : stage === 'NEED_CHECK' ? 'danger' : ['PARTIAL','WAIT_POST','COLLECT'].includes(stage) ? 'warning' : 'info' },
    ticket(row) { return { path: '/oms-supplychain/wmsTickets', query: { sn: row.return_sn, documentId: row.ticket_id || undefined }} },
    openWarehouse(row) { const docs = row.warehouse_documents || []; if (!docs.length) return this.open(row); this.detailSequence++; this.documentSn = docs[0].return_sn; this.documentTab = 'interactions'; this.visible = true },
    async open(row) { if (row.view === 'DOCUMENT') { this.detailSequence++; this.documentSn = row.return_sn; this.documentTab = 'items'; this.visible = true; return } this.documentSn = ''; const seq = ++this.detailSequence; this.visible = true; this.detail = null; this.detailLoading = true; try { const data = (await returnDetail({ view: row.view, key: row.group_key, number: this.query.number, numberType: this.query.numberType })).data; if (seq === this.detailSequence) this.detail = data } finally { if (seq === this.detailSequence) this.detailLoading = false } },
    memberClass({ row }) { return row.matched ? 'matched-source' : '' },
    locateParcel(row) { this.query = { ...defaults(), view: 'PARCEL', numberType: 'PARCEL', number: row.parcel_sn }; this.search() },
    async exportRows() { this.exporting = true; try { const data = (await returnExport(this.filters())).data; if ((data.synchronization || {}).updating || (data.synchronization || {}).warning) { this.$message.warning('查询进度仍在同步，请完成后再导出'); this.load(); return } const lines = [['视图','退货来源/包裹/入库单','售后归属','接收仓','退回承运商','退回运单','应退','已确认实收','已入库','待归属回传数','当前进度','仓库受理状态','最近交互动作','最近交互结果','最近交互时间','最近交互原因','下一步','创建时间']]; (data.rows || []).forEach(row => lines.push([this.currentView.label, this.identity(row), sourceText(row), this.store(row.store_code), row.carrier, row.waybill, quantityText(row.units,'quantity'), quantityText(row.units,'accepted_quantity'), quantityText(row.units,'posted_quantity'), row.pending_count, stageLabels[row.stage], warehouseText(row), interactionActions[(row.latest_interaction||{}).action], interactionResults[(row.latest_interaction||{}).result], (row.latest_interaction||{}).create_time, (row.latest_interaction||{}).error_info, nextStep(row), row.create_time])); const blob = new Blob(['\ufeff' + lines.map(r => r.map(csvCell).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = '退货管理-' + this.currentView.label + '.csv'; a.click(); URL.revokeObjectURL(url) } finally { this.exporting = false } }
  }
}
